import { readdir, stat, readFile } from "node:fs/promises";
import path from "node:path";
const limit = 8388608;
// Paths excluded by the assignment or generated by local installation, at any depth.
const excluded = new Set([
  ".git",
  ".github",
  ".imd",
  ".agents",
  ".codex",
  "node_modules",
  ".cache",
  ".npm",
  ".vite",
]);
const files = [];
async function walk(dir = ".") {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const rel = path.join(dir, entry.name);
    if (excluded.has(entry.name) || rel === "test/scratch") continue;
    if (entry.isSymbolicLink())
      throw new Error(`Symlinks are not part of this submission: ${rel}`);
    if (entry.isDirectory()) await walk(rel);
    else files.push({ path: rel, size: (await stat(rel)).size });
  }
}
await walk();
const total = files.reduce((n, f) => n + f.size, 0);
const html = await readFile("dist/index.html", "utf8");
if (/(?:src|href)=["']\//.test(html))
  throw new Error("Root-absolute URL in production HTML");
for (const f of files.filter(
  (f) => f.path.startsWith("dist/") && f.path.endsWith(".css"),
)) {
  const css = await readFile(f.path, "utf8");
  if (/url\(["']?\//.test(css))
    throw new Error("Root-absolute asset URL in production CSS");
}
if (!files.some((f) => f.path === "package-lock.json"))
  throw new Error("Missing lockfile");
if (total > limit) throw new Error(`Submission exceeds budget: ${total}`);
console.log(
  JSON.stringify(
    {
      files: files.length,
      uncompressedBytes: total,
      budgetBytes: limit,
      remainingBytes: limit - total,
      largest: files.sort((a, b) => b.size - a.size).slice(0, 8),
    },
    null,
    2,
  ),
);
